export class AppError extends Error {
  constructor(status, kode, pesan) { super(pesan); Object.assign(this, { status, kode }); }
}
// === src/repositories/todo.js ===
export function buatTodoRepo() {
  const data = [];
  let nextId = 1;
  return {
    async semuaMilik(penggunaId) { return data.filter((t) => t.penggunaId === penggunaId).map((t) => ({ ...t })); },
    async cari(id) { const t = data.find((x) => x.id === id); return t ? { ...t } : null; },
    async tambah(t) { const baru = { id: nextId++, selesai: false, ...t }; data.push(baru); return { ...baru }; },
    async ubah(id, perubahan) { const t = data.find((x) => x.id === id); Object.assign(t, perubahan); return { ...t }; },
    async hapus(id) { data.splice(data.findIndex((x) => x.id === id), 1); },
  };
}
// === src/services/todo.js ===
import { z } from 'zod';
import { AppError } from '../errors.js';
const TodoBaru = z.object({ judul: z.string().trim().min(1).max(100), prioritas: z.enum(['rendah', 'sedang', 'tinggi']).default('sedang') });
const TodoUbah = z.object({ judul: z.string().trim().min(1).max(100), selesai: z.boolean(), prioritas: z.enum(['rendah', 'sedang', 'tinggi']) }).partial();
function periksa(skema, data) {
  const h = skema.safeParse(data);
  if (!h.success) throw new AppError(400, 'VALIDASI_GAGAL', h.error.issues.map((i) => `${i.path.join('.') || 'body'}: ${i.message}`).join('; '));
  return h.data;
}
const QueryTodo = z.object({
  q: z.string().default(''),
  selesai: z.enum(['true', 'false']).transform((v) => v === 'true').optional(),
  urut: z.enum(['terbaru', 'prioritas']).default('terbaru'),
  halaman: z.coerce.number().int().min(1).default(1),
  per: z.coerce.number().int().min(1).max(50).default(10),
});
export function buatTodoService(repo) {
  async function milik(penggunaId, id) {
    const t = await repo.cari(id);
    if (!t || t.penggunaId !== penggunaId) throw new AppError(404, 'TODO_TIDAK_ADA', `Todo ${id} tidak ada`);
    return t;
  }
  return {
    async daftar(penggunaId, query = {}) {
      const { q, selesai, urut, halaman, per } = periksa(QueryTodo, query);
      let hasil = (await repo.semuaMilik(penggunaId)).filter((t) => t.judul.toLowerCase().includes(q.toLowerCase()) && (selesai === undefined || t.selesai === selesai));
      const bobot = { tinggi: 0, sedang: 1, rendah: 2 };
      hasil = hasil.toSorted(urut === 'prioritas' ? (a, b) => bobot[a.prioritas] - bobot[b.prioritas] || a.id - b.id : (a, b) => b.id - a.id);
      const mulai = (halaman - 1) * per;
      return { data: hasil.slice(mulai, mulai + per), meta: { total: hasil.length, halaman, per, jumlahHalaman: Math.ceil(hasil.length / per) } };
    },
    detail: milik,
    async tambah(penggunaId, masukan) { return repo.tambah({ ...periksa(TodoBaru, masukan), penggunaId }); },
    async ubah(penggunaId, id, masukan) { await milik(penggunaId, id); return repo.ubah(id, periksa(TodoUbah, masukan)); },
    async hapus(penggunaId, id) { await milik(penggunaId, id); await repo.hapus(id); },
  };
}
// === main.js ===
import { buatTodoRepo } from './src/repositories/todo.js';
import { buatTodoService } from './src/services/todo.js';
const todo = buatTodoService(buatTodoRepo());
for (const [judul, prioritas] of [['Beli kopi', 'rendah'], ['Bayar listrik', 'tinggi'], ['Kopi darat komunitas', 'sedang'], ['Rapat tim', 'tinggi'], ['Cuci motor', 'rendah']]) {
  await todo.tambah(1, { judul, prioritas });
}
await todo.ubah(1, 2, { selesai: true });
const judul = (h) => h.data.map((t) => t.judul);
console.log(judul(await todo.daftar(1, { q: 'kopi' })));
console.log(judul(await todo.daftar(1, { selesai: 'false', urut: 'prioritas', per: '2' })));
console.log((await todo.daftar(1, { per: '2', halaman: '3' })).meta);
try {
  await todo.daftar(1, { per: '500' });
} catch (e) {
  console.log(e.status, e.kode);
}

